// Grammar
// =============================================================================

/// Node spans and rule ids are recorded (`@schema` or `--spans`).
pub const nodeStore = true;
/// Element extents are kept for side-band labels and nested nodes.
const elemEnds = true;
/// Lists keep trailing nils: positions are fixed by the schema.
const keepTrailingNils = true;
const hasTrivia = false;
const hasRepair = false;
const numSymbols = 189;
const endSymbol: u16 = 1;
const errorSymbol: u16 = 2;

fn tokenToSymbol(_: *BaseParser, token: Token) u16 {
    return switch (token.cat) {
        .@"eof" => 1,
        .@"newline" => 68,
        .@"indent" => 69,
        .@"outdent" => 70,
        .@"ident" => 72,
        .@"post_if" => 73,
        .@"new" => 77,
        .@"drop_stmt" => 78,
        .@"return" => 79,
        .@"break" => 80,
        .@"continue" => 81,
        .@"defer" => 82,
        .@"errdefer" => 83,
        .@"raw" => 84,
        .@"pub" => 95,
        .@"use" => 96,
        .@"fun" => 97,
        .@"sub" => 98,
        .@"lparen_call" => 102,
        .@"pre" => 104,
        .@"read_pfx" => 105,
        .@"write_pfx" => 106,
        .@"kwarg_name" => 107,
        .@"enum" => 108,
        .@"error" => 109,
        .@"struct" => 110,
        .@"type" => 111,
        .@"drop" => 112,
        .@"test" => 115,
        .@"string_dq" => 116,
        .@"string_sq" => 117,
        .@"extern" => 118,
        .@"share_pfx" => 119,
        .@"integer" => 123,
        .@"suffix_q" => 127,
        .@"suffix_bang" => 128,
        .@"catch" => 130,
        .@"bar_capture" => 131,
        .@"ternary_if" => 132,
        .@"else" => 133,
        .@"or" => 134,
        .@"and" => 135,
        .@"not" => 136,
        .@"as" => 138,
        .@"if" => 139,
        .@"while" => 140,
        .@"for" => 141,
        .@"in" => 142,
        .@"match" => 143,
        .@"minus_prefix" => 146,
        .@"true" => 147,
        .@"false" => 148,
        .@"dot_lit" => 149,
        .@"bar_empty" => 155,
        .@"clone_pfx" => 156,
        .@"move_pfx" => 157,
        .@"lbracket_index" => 158,
        .@"real" => 159,
        .@"colon" => 71,
        .@"assign" => 76,
        .@"rparen" => 100,
        .@"comma" => 101,
        .@"lparen" => 103,
        .@"tilde" => 120,
        .@"lbracket" => 121,
        .@"rbracket" => 122,
        .@"dot" => 129,
        .@"at" => 160,
        .@"lt" => 174,
        .@"gt" => 175,
        .@"bar" => 179,
        .@"caret" => 180,
        .@"ampersand" => 181,
        .@"plus" => 184,
        .@"minus" => 185,
        .@"star" => 186,
        .@"slash" => 187,
        .@"percent" => 188,
        .@"fixed_assign" => 74,
        .@"move_assign" => 75,
        .@"plus_assign" => 85,
        .@"minus_assign" => 86,
        .@"star_assign" => 87,
        .@"slash_assign" => 88,
        .@"percent_assign" => 89,
        .@"amp_assign" => 90,
        .@"bar_assign" => 91,
        .@"caret_assign" => 92,
        .@"lshift_assign" => 93,
        .@"rshift_assign" => 94,
        .@"arrow" => 99,
        .@"fat_arrow" => 144,
        .@"dotdot" => 145,
        .@"eq" => 172,
        .@"ne" => 173,
        .@"le" => 176,
        .@"ge" => 177,
        .@"nullish" => 178,
        .@"lshift" => 182,
        .@"rshift" => 183,
