    };
}

fn executeAction(self: *BaseParser, ruleId: u16, pass: []Sexp) Sexp {
    @setEvalBranchQuota(1_000_000);
    return switch (ruleId) {
        0 => self.build(&.{ .{ .tag = .@"module" } }, .tree),
        1 => blk: { var out: std.ArrayListUnmanaged(Sexp) = .empty; out.append(self.allocator(), .{ .tag = .@"module" }) catch break :blk self.oomNil(); for (pass[0].items()) |item| out.append(self.allocator(), item) catch break :blk self.oomNil(); break :blk self.finishList(&out, .tree); },
        2 => self.build(&.{ pass[0] }, .spread),
        3 => blk: { var out = self.extendList(pass[0]) catch break :blk self.oomNil(); out.append(self.allocator(), pass[2]) catch break :blk self.oomNil(); break :blk self.keepList(&out, .spread); },
        4 => pass[0],
        5 => self.build(&.{ .{ .tag = .@"block" } }, .tree),
        6 => blk: { var out: std.ArrayListUnmanaged(Sexp) = .empty; out.append(self.allocator(), .{ .tag = .@"block" }) catch break :blk self.oomNil(); for (pass[1].items()) |item| out.append(self.allocator(), item) catch break :blk self.oomNil(); break :blk self.finishList(&out, .tree); },
        7 => pass[0],
        8 => pass[0],
        9 => pass[0],
        10 => pass[0],
        11 => pass[0],
        12 => self.build(&.{ .{ .tag = .@"labeled" }, pass[1], pass[2] }, .tree),
        13 => pass[0],
        14 => self.build(&.{ .{ .tag = .@"if" }, pass[2], self.nested(self.build(&.{ .{ .tag = .@"block" }, pass[0] }, .tree), 0, 0), .nil }, .tree),
        15 => pass[0],
        16 => pass[0],
        17 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"fixed" }, pass[0], .nil, pass[2] }, .tree),
        18 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"move" }, pass[0], .nil, pass[2] }, .tree),
        19 => self.build(&.{ .{ .tag = .@"set" }, .nil, pass[0], pass[2], pass[4] }, .tree),
        20 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"fixed" }, pass[0], pass[2], pass[4] }, .tree),
        21 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"shadow" }, pass[1], .nil, pass[3] }, .tree),
        22 => self.build(&.{ .{ .tag = .@"drop" }, pass[1] }, .tree),
        23 => self.build(&.{ .{ .tag = .@"return" }, .nil }, .tree),
        24 => self.build(&.{ .{ .tag = .@"return" }, pass[1] }, .tree),
        25 => self.build(&.{ .{ .tag = .@"break" }, .nil, .nil }, .tree),
        26 => self.build(&.{ .{ .tag = .@"break" }, .nil, pass[2] }, .tree),
        27 => self.build(&.{ .{ .tag = .@"break" }, pass[1], .nil }, .tree),
        28 => self.build(&.{ .{ .tag = .@"break" }, pass[3], pass[2] }, .tree),
        29 => self.build(&.{ .{ .tag = .@"continue" }, .nil }, .tree),
        30 => self.build(&.{ .{ .tag = .@"continue" }, pass[2] }, .tree),
        31 => self.build(&.{ .{ .tag = .@"defer" }, pass[1] }, .tree),
        32 => self.build(&.{ .{ .tag = .@"defer" }, pass[1] }, .tree),
        33 => self.build(&.{ .{ .tag = .@"errdefer" }, pass[1] }, .tree),
        34 => self.build(&.{ .{ .tag = .@"errdefer" }, pass[1] }, .tree),
        35 => self.build(&.{ .{ .tag = .@"raw_block" }, pass[1] }, .tree),
        36 => self.build(&.{ .{ .tag = .@"set" }, .nil, pass[0], .nil, pass[2] }, .tree),
        37 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"+=" }, pass[0], .nil, pass[2] }, .tree),
        38 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"-=" }, pass[0], .nil, pass[2] }, .tree),
        39 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"*=" }, pass[0], .nil, pass[2] }, .tree),
